//! Compare Rust string output to bytes generated by Go's encoding/json.

#![allow(clippy::expect_used, clippy::unwrap_used)]

use zoli_intel::wire::{Mode, write_string};

const FIXTURES: &str = include_str!("../../../testdata/conformance/wire-strings.tsv");

fn decode_hex(value: &str) -> Vec<u8> {
    assert_eq!(value.len() % 2, 0, "fixture hex must contain whole bytes");
    value
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| {
            let text = std::str::from_utf8(pair).unwrap();
            u8::from_str_radix(text, 16).expect("valid generated fixture hex")
        })
        .collect()
}

#[test]
fn strings_match_go_in_both_modes() {
    let mut count = 0;
    for row in FIXTURES.lines().filter(|line| !line.starts_with('#')) {
        let columns: Vec<_> = row.split('\t').collect();
        assert_eq!(columns.len(), 4, "fixture row {row:?}");
        let input = String::from_utf8(decode_hex(columns[1])).unwrap();
        for (mode, expected) in [(Mode::Hash, columns[2]), (Mode::Marshal, columns[3])] {
            let mut actual = String::new();
            write_string(&mut actual, &input, mode);
            if mode == Mode::Hash {
                actual.push('\n');
            }
            assert_eq!(
                actual.as_bytes(),
                decode_hex(expected),
                "{}: {mode:?}",
                columns[0]
            );
        }
        count += 1;
    }
    // An empty or accidentally truncated corpus must not count as conformance.
    assert!(count >= 43, "the Go string fixture corpus is incomplete");
}

#[test]
fn string_writer_appends_without_adding_row_delimiters() {
    let mut output = String::from("[");
    write_string(&mut output, "first", Mode::Hash);
    output.push(',');
    write_string(&mut output, "second", Mode::Marshal);
    output.push(']');
    assert_eq!(output, r#"["first","second"]"#);
}
